jQuery(function($){
	$('.gnb > ul > li > a').on('mouseenter', function(){
		$(this).next().stop().slideDown();
	});
	$('.gnb > ul > li').on('mouseleave', function(){
		$(this).children('ul').stop().slideUp();
	});
	$('.m_gnb > ul > li > a').on('click', function(){
		$(this).parent().toggleClass('active').siblings().removeClass('active');
		$(this).next().stop().slideToggle().parent().siblings().children('ul').stop().slideUp();
	});
	$('.open_gnb').on('click', function(){
		$('.m_gnb_area .gnb_wrap').stop().fadeIn();
	});
	$('.close_gnb').on('click', function(){
		$('.m_gnb_area .gnb_wrap').stop().fadeOut();
	});
	$('#mv .mv').slick({
    arrows: false,
    dots: true,
    autoplay: true,
	  autoplaySpeed: 7500,
    infinite: true,
	});
	/*
	var mv = $('.mv').bxSlider({
		auto:true,
		autoControls: true,
		pause:7500,
		touchEnabled : (navigator.maxTouchPoints > 0),
	});
	*/

	var m2_slide = $('.m2 .wrap .slide_wrap .slide').bxSlider({
		mode:'vertical',
		pagerCustom: '.m2 .wrap .slide_nav .dep1_wrap'
	});

	var m3_auto_height = function(){
		var height = $('.m3 .wrap .con1 .inner').outerHeight();
		$('.m3 .wrap .con2 .inner, .m3 .wrap .con3 .inner').css({'height':height});
	}

	$(window).load(function(){
		m3_auto_height();
	});

	$(window).resize(function(){
		m3_auto_height();
	});
});